PROJECT_DIR = Path(__file__).resolve().parent
MAPS_DIR = PROJECT_DIR / "field_maps"


def saved_maps(with_data=False):
    """Field maps saved in field_maps/ (not the autosave or the robot model),
    newest first."""
    found = []
    for path in MAPS_DIR.glob("*.json") if MAPS_DIR.is_dir() else []:
        if path.stem.startswith("_"):
            continue
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if not isinstance(data, dict) or data.get("version") != 1 or "field" not in data:
            continue
        st = path.stat()
        item = {"name": path.stem, "mtime": st.st_mtime, "size": st.st_size}
        if with_data:
            data = dict(data)
            data.pop("bg", None)   # photos are big; the preview draws without them
            item["map"] = data
        found.append(item)
    found.sort(key=lambda m: -m["mtime"])
    return found
