JAVA_CONST_RE = re.compile(
    r"^(?P<pre>[ \t]*(?:(?:public|private|protected|final)\s+)*static\s+final\s+"
    r"(?P<type>double|int|long|float|boolean)\s+(?P<name>[A-Z][A-Z0-9_]*)\s*=\s*)"
    r"(?P<val>-?[\d_]+(?:\.\d+)?[dDfFlL]?|true|false)\s*;(?P<post>.*)$", re.M)
JAVA_TUNABLE_RE = re.compile(
    r"^(?P<pre>[ \t]*(?:(?:public|private|protected|static|final)\s+)*Tunable\s+(?P<name>\w+)\s*=\s*"
    r"new\s+Tunable\(\s*\"[^\"]*\"\s*,\s*)(?P<val>-?\d+(?:\.\d+)?)(?P<post>\s*\).*)$", re.M)
PY_CONST_RE = re.compile(
    r"^(?P<pre>(?P<name>[A-Z][A-Z0-9_]*)\s*=\s*(?:(?P<cast>int|float)\(os\.getenv\(\"\w+\",\s*\")?)"
    r"(?P<val>-?\d+(?:\.\d+)?|True|False)(?P<post>(?:\"\)\))?\s*(?:#.*)?)$", re.M)

