def pack_offline(dst, light=False):
    """light: the small set of wheels into field_planner.py itself.
    Otherwise the folder MapperX_offline/ with MapperX_offline.py (all
    wheels, portable Pythons, the project) and the two launchers."""
    files = sorted(WHEELS_DIR.glob("*.whl")) if WHEELS_DIR.is_dir() else []
    if light:
        files = [f for f in files if WHEELS_LIGHT.match(f.name)]
    if not files:
        raise ValueError("Нет пакетов в %s" % WHEELS_DIR)
    pythons = [] if light else sorted(PYTHONS_DIR.glob("*.tar.gz")) if PYTHONS_DIR.is_dir() else []
    code, vault = _split_self()
    dst = Path(dst)
    if not light:
        dst.mkdir(parents=True, exist_ok=True)
        for name, text, nl in (("Запустить MapperX (Mac).command", LAUNCH_MAC, "\n"),
                               ("Запустить MapperX (Windows).cmd", LAUNCH_WIN, "\r\n")):
            with open(dst / name, "w", encoding="utf-8", newline=nl) as f:   # Python 3.9: no write_text(newline=)
                f.write(text)
        os.chmod(dst / "Запустить MapperX (Mac).command", 0o755)
        dst = dst / "MapperX_offline.py"
    tmp = Path(str(dst) + ".tmp")
    if light:
        with open(tmp, "w", encoding="utf-8", newline="\n") as out:
            out.write(code.rstrip("\n") + "\n")
            with tempfile_zip(files) as (zf, size):
                _b64_block(out, WHEELS_BEGIN, WHEELS_END, {"created": time.strftime("%Y-%m-%d %H:%M:%S"),
                                                          "wheels": len(files), "bytes": size}, zf)
            if vault:
                out.write("\n\n" + vault.lstrip("\n"))
    else:
        _write_offline(tmp, files, pythons, vault, code)
    os.replace(tmp, dst)
    return len(files), len(pythons), dst, dst.stat().st_size


class tempfile_zip:
    """with tempfile_zip(files) as (fileobj, size): the wheels as one stored zip."""
    def __init__(self, files):
        import tempfile
        self.tmp = tempfile.TemporaryFile()
        with zipfile.ZipFile(self.tmp, "w", zipfile.ZIP_STORED) as z:
            for f in files:
                z.write(f, f.name)

    def __enter__(self):
        size = self.tmp.tell()
        self.tmp.seek(0)
        return self.tmp, size

    def __exit__(self, *_exc):
        self.tmp.close()


def setup_status(_request):
    frozen = bool(getattr(sys, "frozen", False))
    return {"os": setup_os(), "python": sys.version.split()[0], "executable": sys.executable,
            "frozen": frozen, "missing": [] if frozen else setup_missing(),
            "running": SETUP_STATE["running"], "ok": SETUP_STATE["ok"], "log": SETUP_STATE["log"][-12:]}


def setup_pack_update(_request):
    dst, size = pack_update(SELF_PATH.parent / "MapperX_update")
    return {"path": str(dst), "size": size}


def setup_pack(_request):
    """VaultX: one offline file (MapperX_offline.py) with every package inside."""
    if any(not j.done for j in JOBS.values()):
        raise ValueError("Уже идёт другая задача")
    job_id = secrets.token_hex(4)
    JOBS[job_id] = Job("Офлайн-файл", [sys.executable, str(SELF_PATH), "--pack-offline"])
    return {"id": job_id}


# ── Network updates: a Mac shares the MapperX code + project backup (a few MB);
# a MapperX_offline elsewhere takes them and keeps its own Pythons / packages ──

UPDATE_PORT = 8767
UPDATE = {"server": None, "code": None, "until": 0, "fails": 0, "log": [], "payload": None,
          "tunnel": None, "public_url": None, "clients": {}}
UPDATE_LOCK = threading.Lock()   # UPDATE["clients"] / "fails" are touched by the handler threads
UPDATE_MAX_CLIENTS = 50
# Receiver side: the single background apply and its progress (read by /update/progress).
UPAPPLY = {"running": False, "stage": "idle", "pct": 0, "got": 0, "total": 0, "speed": 0, "eta": None,
           "error": None, "done": False, "result": None}
UPAPPLY_LOCK = threading.Lock()
# Public half of the owner's update-signing key (hex, 32 bytes). Empty = updates are not signed.
# It lives in the code part, so it travels with every update. The private key is never in this file.
UPDATE_PUBKEY = "4af53e1686ae616664cb86932afdca884d74315fe09c7d9c50193732615b7832"
UPDATE_KEY_PATH = "~/.mapperx/update_signing.key"

# ── Ed25519 (RFC 8032), pure Python, stdlib only ──
_ED_P = 2 ** 255 - 19
_ED_L = 2 ** 252 + 27742317777372353535851937790883648493
_ED_D = -121665 * pow(121666, _ED_P - 2, _ED_P) % _ED_P
_ED_I = pow(2, (_ED_P - 1) // 4, _ED_P)


def _ed_add(a, b):
    a1 = (a[1] - a[0]) * (b[1] - b[0]) % _ED_P
    b1 = (a[1] + a[0]) * (b[1] + b[0]) % _ED_P
    c1 = 2 * a[3] * b[3] * _ED_D % _ED_P
    d1 = 2 * a[2] * b[2] % _ED_P
    e, f, g, h = b1 - a1, d1 - c1, d1 + c1, b1 + a1
    return (e * f % _ED_P, g * h % _ED_P, f * g % _ED_P, e * h % _ED_P)


def _ed_mul(s, pt):
    r = (0, 1, 1, 0)
    while s > 0:
        if s & 1:
            r = _ed_add(r, pt)
        pt = _ed_add(pt, pt)
        s >>= 1
    return r


def _ed_enc(pt):
    zi = pow(pt[2], _ED_P - 2, _ED_P)
    x, y = pt[0] * zi % _ED_P, pt[1] * zi % _ED_P
    return (y | ((x & 1) << 255)).to_bytes(32, "little")


def _ed_dec(raw):
    if len(raw) != 32:
        return None
    n = int.from_bytes(raw, "little")
    y, sign = n & ((1 << 255) - 1), n >> 255
    if y >= _ED_P:
        return None
    x2 = (y * y - 1) * pow(_ED_D * y * y + 1, _ED_P - 2, _ED_P) % _ED_P
    x = pow(x2, (_ED_P + 3) // 8, _ED_P)
    if (x * x - x2) % _ED_P:
        x = x * _ED_I % _ED_P
    if (x * x - x2) % _ED_P:
        return None
    if x == 0 and sign:
        return None
    if (x & 1) != sign:
        x = _ED_P - x
    return (x, y, 1, x * y % _ED_P)


_ED_G = _ed_dec((4 * pow(5, _ED_P - 2, _ED_P) % _ED_P).to_bytes(32, "little"))


def _ed_secret(seed):
    import hashlib
    h = hashlib.sha512(seed).digest()
    a = int.from_bytes(h[:32], "little")
    a &= (1 << 254) - 8
    a |= 1 << 254
    return a, h[32:]


def _ed25519_public(seed):
    return _ed_enc(_ed_mul(_ed_secret(seed)[0], _ED_G))


def _ed25519_sign(seed, msg):
    import hashlib
    a, prefix = _ed_secret(seed)
    pub = _ed_enc(_ed_mul(a, _ED_G))
    r = int.from_bytes(hashlib.sha512(prefix + msg).digest(), "little") % _ED_L
    rr = _ed_enc(_ed_mul(r, _ED_G))
    k = int.from_bytes(hashlib.sha512(rr + pub + msg).digest(), "little") % _ED_L
    return rr + ((r + k * a) % _ED_L).to_bytes(32, "little")


def _ed25519_verify(pub, msg, sig):
    """True only for a valid signature; any malformed input gives False."""
    import hashlib
    try:
        if len(pub) != 32 or len(sig) != 64:
            return False
        a_pt, r_pt = _ed_dec(pub), _ed_dec(sig[:32])
        s = int.from_bytes(sig[32:], "little")
        if a_pt is None or r_pt is None or s >= _ED_L:
            return False
        k = int.from_bytes(hashlib.sha512(sig[:32] + pub + msg).digest(), "little") % _ED_L
        return _ed_enc(_ed_mul(s, _ED_G)) == _ed_enc(_ed_add(r_pt, _ed_mul(k, a_pt)))
    except Exception:
        return False


def _update_seed():
    """The owner's private seed (32 bytes) or None."""
    try:
        raw = bytes.fromhex(Path(os.path.expanduser(UPDATE_KEY_PATH)).read_text(encoding="utf-8").strip())
        return raw if len(raw) == 32 else None
    except (OSError, ValueError):
        return None


def _update_key_state():
    seed = _update_seed()
    if seed is None:
        return "none"
    return "ok" if UPDATE_PUBKEY and _ed25519_public(seed).hex() == UPDATE_PUBKEY else "mismatch"


def _sig_state(sig_hex, digest_hex):
    """true / false (no signature or nothing to check against) / "bad" for a claimed sha256 digest."""
    if not UPDATE_PUBKEY or not sig_hex:
        return False
    try:
        return bool(_ed25519_verify(bytes.fromhex(UPDATE_PUBKEY), bytes.fromhex(digest_hex), bytes.fromhex(sig_hex))) or "bad"
    except (ValueError, TypeError):
        return "bad"


def update_key(request):
    """VaultX: create the owner's signing key and write its public half into this file."""
    global UPDATE_PUBKEY
    key_path = Path(os.path.expanduser(UPDATE_KEY_PATH))
    if request.get("create"):
        if _update_seed() is not None and not request.get("force"):
            return {"needForce": True, "keyState": _update_key_state()}
        seed = secrets.token_bytes(32)
        pub = _ed25519_public(seed).hex()
        text = SELF_PATH.read_text(encoding="utf-8")
        new, n = re.subn(r'(?m)^UPDATE_PUBKEY = "[0-9a-f]*"$', 'UPDATE_PUBKEY = "%s"' % pub, text, count=1)
        if n != 1:
            raise ValueError("Не нашёл UPDATE_PUBKEY в файле MapperX")
        compile(new, str(SELF_PATH), "exec")   # never write code that would not start
        tmp = Path(str(SELF_PATH) + ".update")
        with open(tmp, "w", encoding="utf-8", newline="\n") as out:
            out.write(new)
        os.replace(tmp, SELF_PATH)
        UPDATE_PUBKEY = pub
        key_path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        ktmp = Path(str(key_path) + ".tmp")
        fd = os.open(str(ktmp), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, "w") as f:
            f.write(seed.hex() + "\n")
        os.replace(ktmp, key_path)
    return {"keyState": _update_key_state(), "pubkey": UPDATE_PUBKEY, "keyPath": str(key_path)}


def _tunnel_stop():
    proc, UPDATE["tunnel"], UPDATE["public_url"] = UPDATE["tunnel"], None, None
    if proc is not None:
        try:
            proc.terminate()
            proc.wait(timeout=5)
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass


def _find_cloudflared():
    for cand in (shutil.which("cloudflared"), "/opt/homebrew/bin/cloudflared", "/usr/local/bin/cloudflared"):
        if cand and os.path.isfile(cand) and os.access(cand, os.X_OK):
            return cand
    return None


def _tunnel_start(exe):
    proc = subprocess.Popen([exe, "tunnel", "--no-autoupdate", "--url", "http://localhost:%d" % UPDATE_PORT],
                            stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)
    UPDATE["tunnel"], UPDATE["public_url"] = proc, None

    def reader():
        try:
            for line in proc.stdout:
                m = re.search(r"https://[a-z0-9-]+\.trycloudflare\.com", line)
                if m and UPDATE["tunnel"] is proc and not UPDATE["public_url"]:
                    UPDATE["public_url"] = m.group(0)
        except (OSError, ValueError):
            pass

    def watcher():   # the tunnel never outlives the share (stop / 30 min / lockout)
        while proc.poll() is None:
            if UPDATE["tunnel"] is not proc:
                return
            if time.time() > UPDATE["until"] or UPDATE["fails"] >= 20 or UPDATE["server"] is None:
                if UPDATE["tunnel"] is proc:
                    _tunnel_stop()
                return
            time.sleep(2)

    threading.Thread(target=reader, daemon=True).start()
    threading.Thread(target=watcher, daemon=True).start()


import atexit
atexit.register(_tunnel_stop)


def _local_ips():
    import socket
    ips = []
    try:   # the address used to reach the LAN (no packet is sent)
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("10.255.255.255", 1))
        ips.append(s.getsockname()[0])
        s.close()
    except OSError:
        pass
    try:
        for info in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET):
            if info[4][0] not in ips and not info[4][0].startswith("127."):
                ips.append(info[4][0])
    except OSError:
        pass
    return ips


def _update_payload():
    """gzip(JSON): this MapperX's code (without the packages/Pythons blocks)
    and its project backup."""
    import gzip
    import hashlib
    code, vault = _split_self()
    digest = hashlib.sha256((code + vault).encode("utf-8")).digest()
    body = {"version": SERVER_STAMP, "created": time.strftime("%Y-%m-%d %H:%M:%S"), "code": code, "vault": vault,
            "from": socket_hostname(), "sha256": digest.hex()}
    if _update_key_state() == "ok":   # signed with the owner's key; the seed is read only to sign
        body["sig"] = _ed25519_sign(_update_seed(), digest).hex()
    return gzip.compress(json.dumps(body, ensure_ascii=False).encode("utf-8"), 6)


def socket_hostname():
    import socket
    try:
        return socket.gethostname()
    except OSError:
        return "?"


class _UpdateHandler(BaseHTTPRequestHandler):
    def log_message(self, _format, *_args):
        pass

    def _client_ip(self):
        ip = self.client_address[0]
        if ip in ("127.0.0.1", "::1"):   # only the local cloudflared may tell the real address
            real = (self.headers.get("CF-Connecting-IP") or "").strip()
            if re.match(r"^[0-9A-Fa-f:.]{2,45}$", real):
                ip = real
        return ip

    def _client_entry(self, q):
        """The tracking entry of this receiver (created on first call). The name is display-only."""
        cid = q.get("id", [""])[0]
        if not re.match(r"^[A-Za-z0-9_-]{6,32}$", cid):
            cid = secrets.token_hex(6)
        name = "".join(c for c in q.get("name", [""])[0] if c.isprintable()).strip()[:40] or "?"
        now = time.time()
        with UPDATE_LOCK:
            clients = UPDATE["clients"]
            c = clients.get(cid)
            if c is None:
                while len(clients) >= UPDATE_MAX_CLIENTS:
                    del clients[min(clients, key=lambda k: clients[k]["last"])]
                c = clients[cid] = {"id": cid, "t0": now}
            c.update(name=name, ip=self._client_ip(), sent=0, total=0, speed=0, state="dl", t0=now, last=now)
        return c

    def do_GET(self):
        from urllib.parse import parse_qs, urlparse
        q = parse_qs(urlparse(self.path).query)
        if time.time() > UPDATE["until"] or UPDATE["fails"] >= 20:
            self.send_response(410)
            self.end_headers()
            return
        if q.get("code", [""])[0] != UPDATE["code"]:
            with UPDATE_LOCK:
                UPDATE["fails"] += 1
            self.send_response(403)
            self.end_headers()
            return
        path = urlparse(self.path).path
        if path == "/mapperx-update/done":   # the receiver reports the install; marks its entry, nothing else
            with UPDATE_LOCK:
                c = UPDATE["clients"].get(q.get("id", [""])[0])
                if c is not None:
                    c.update(state="done" if q.get("ok", [""])[0] == "1" else "fail", last=time.time())
            data = b"{}"
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
            return
        client = None
        if path == "/mapperx-update/info":
            data = json.dumps({"version": SERVER_STAMP, "from": socket_hostname(),
                               "size": len(UPDATE["payload"] or b""), "sha256": UPDATE.get("sha256"),
                               "sig": UPDATE.get("sig")}).encode("utf-8")
            ctype = "application/json"
        else:
            data = UPDATE["payload"] or b""
            ctype = "application/octet-stream"
            client = self._client_entry(q)
            client["total"] = len(data)
            UPDATE["log"].append("%s — %s (%s) забрал обновление" % (time.strftime("%H:%M:%S"), client["ip"], client["name"]))
        self.send_response(200)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        if client is None:
            self.wfile.write(data)
            return
        t_speed, b_speed = time.time(), 0   # speed over ~0.5 s windows
        try:
            for pos in range(0, len(data), 65536):
                self.wfile.write(data[pos:pos + 65536])
                now = time.time()
                client["sent"] = min(len(data), pos + 65536)
                client["last"] = now
                if now - t_speed >= 0.5:
                    client["speed"] = int((client["sent"] - b_speed) / (now - t_speed))
                    t_speed, b_speed = now, client["sent"]
            client["speed"], client["last"] = 0, time.time()
            if client["state"] == "dl":   # /done may already have arrived
                client["state"] = "got"
        except OSError:   # the receiver went away mid-download
            client["speed"], client["last"] = 0, time.time()
            if client["state"] == "dl":
                client["state"] = "fail"


def update_share(request):
    """VaultX: start / stop sharing the update on the LAN (30 min, 6-digit code)."""
    exe = None
    if request.get("internet") and not request.get("stop"):
        if _update_key_state() != "ok":
            raise ValueError("Сначала создайте ключ подписи")
        exe = _find_cloudflared()
        if not exe:
            raise ValueError("cloudflared не найден — установите: brew install cloudflared")
    if UPDATE["server"] is not None:
        UPDATE["server"].shutdown()
        UPDATE["server"].server_close()
        UPDATE["server"] = None
    _tunnel_stop()
    if request.get("stop"):
        return update_status({})
    if request.get("backup", True):
        vault_update({})   # the project in the update is the current one
    UPDATE.update(code="%06d" % secrets.randbelow(1000000), until=time.time() + 1800, fails=0, log=[],
                  payload=_update_payload(), clients={})
    import gzip
    info = json.loads(gzip.decompress(UPDATE["payload"]).decode("utf-8"))
    UPDATE.update(sha256=info.get("sha256"), sig=info.get("sig"))   # /info shows what the payload claims
    server = ThreadingHTTPServer(("0.0.0.0", UPDATE_PORT), _UpdateHandler)
    threading.Thread(target=server.serve_forever, daemon=True).start()
    UPDATE["server"] = server
    if exe:
        try:
            _tunnel_start(exe)
        except OSError as e:
            update_share({"stop": True})
            raise ValueError("Не удалось запустить cloudflared: %s" % e)
    return update_status({})


def update_status(_request):
    on = UPDATE["server"] is not None and time.time() < UPDATE["until"] and UPDATE["fails"] < 20
    if not on:
        _tunnel_stop()
    with UPDATE_LOCK:
        rows = sorted(UPDATE["clients"].values(), key=lambda c: c["t0"])[-20:]
        clients = [{k: c.get(k) for k in ("id", "name", "ip", "sent", "total", "speed", "state")} for c in rows]
        states = [c["state"] for c in UPDATE["clients"].values()]
        counts = {"dl": states.count("dl"), "got": states.count("got") + states.count("done"),
                  "done": states.count("done"), "fails": UPDATE["fails"]}
    return {"on": on, "public_url": UPDATE["public_url"] if on else None, "keyState": _update_key_state(),
            "pubkey": UPDATE_PUBKEY, "internet": on and UPDATE["tunnel"] is not None, "code": UPDATE["code"] if on else None, "ips": _local_ips(), "port": UPDATE_PORT,
            "left": max(0, int(UPDATE["until"] - time.time())) if on else 0,
            "size": len(UPDATE["payload"] or b"") if on else 0, "log": UPDATE["log"][-8:],
            "version": SERVER_STAMP, "clients": clients, "counts": counts}


def _update_url(request, path):
    addr = str(request.get("addr", "")).strip().replace("http://", "")
    code = str(request.get("code", "")).strip()
    if re.match(r"^https://[\w.\-]+(:\d+)?/?$", addr):
        if not re.match(r"^\d{6}$", code):
            raise ValueError("Код — 6 цифр, он показан на Mac")
        return "%s%s?code=%s" % (addr.rstrip("/"), path, code)
    addr = addr.rstrip("/")
    if not addr or not re.match(r"^[\w.\-]+(:\d+)?$", addr):
        raise ValueError("Укажите адрес Mac, например 10.200.191.244 или https://….trycloudflare.com")
    if not re.match(r"^\d{6}$", code):
        raise ValueError("Код — 6 цифр, он показан на Mac")
    if ":" not in addr:
        addr += ":%d" % UPDATE_PORT
    return "http://%s%s?code=%s" % (addr, path, code)


def _update_get(url, timeout, progress=None):
    """GET url. With progress(got, total) the body is read in 64 KB pieces."""
    import ssl
    import urllib.error
    import urllib.request

    def read(r):
        if progress is None:
            return r.read()
        total, buf = int(r.headers.get("Content-Length") or 0), bytearray()
        progress(0, total)
        while True:
            chunk = r.read(65536)
            if not chunk:
                return bytes(buf)
            buf += chunk
            progress(len(buf), total)
    try:
        try:
            with urllib.request.urlopen(url, timeout=timeout) as r:
                return read(r)
        except (urllib.error.URLError, ssl.SSLError) as e:
            bad_cert = isinstance(e, ssl.SSLCertVerificationError) \
                or isinstance(getattr(e, "reason", None), ssl.SSLCertVerificationError)
            if not (bad_cert and url.startswith("https://") and os.path.isfile("/etc/ssl/cert.pem")):
                raise
            # portable Python without root certificates: try the system bundle (verification stays on)
            ctx = ssl.create_default_context(cafile="/etc/ssl/cert.pem")
            with urllib.request.urlopen(url, timeout=timeout, context=ctx) as r:
                return read(r)
    except urllib.error.HTTPError as e:
        raise ValueError({403: "Неверный код", 410: "Раздача на Mac выключена или истекла — включите заново"}.get(
            e.code, "Ошибка %d" % e.code))
    except (urllib.error.URLError, OSError) as e:
        raise ValueError("Mac не отвечает (%s). Оба в одной сети Wi-Fi? Раздача включена?" % getattr(e, "reason", e))


def update_check(request):
    info = json.loads(_update_get(_update_url(request, "/mapperx-update/info"), 5))
    signed = _sig_state(info.get("sig"), info.get("sha256") or "")   # the real check is in update_apply
    return {"remote": info, "local": SERVER_STAMP, "signed": signed}


def _upapply_set(**kw):
    with UPAPPLY_LOCK:
        UPAPPLY.update(kw)


def _update_apply_run(request, url):
    """The background part of update_apply: stages connect -> download -> verify -> install."""
    import gzip
    import hashlib
    from urllib.parse import quote
    cid = secrets.token_urlsafe(9)   # [A-Za-z0-9_-], lets the sender follow this download
    t0 = time.time()
    state = {"t": t0, "b": 0, "speed": 0}

    def progress(got, total):
        now = time.time()
        if now - state["t"] >= 0.5:
            state["speed"], state["t"], state["b"] = int((got - state["b"]) / (now - state["t"])), now, got
        speed = state["speed"] or (got / max(now - t0, 0.001) if got else 0)
        eta = int((total - got) / speed) if speed and total > got else 0
        pct = 5 + (75 * got / total if total else 0)
        _upapply_set(stage="download", pct=int(pct), got=got, total=total, speed=int(speed), eta=eta)
    try:
        _upapply_set(stage="connect", pct=2)
        raw = _update_get("%s&id=%s&name=%s" % (url, cid, quote(socket_hostname())), 120, progress)
        _upapply_set(stage="verify", pct=85, speed=0, eta=0)
        try:
            body = json.loads(gzip.decompress(raw).decode("utf-8"))
        except (OSError, EOFError, ValueError):
            raise ValueError("Обновление пришло повреждённым — попробуйте ещё раз")
        code, vault = body.get("code", ""), body.get("vault", "")
        digest = hashlib.sha256((code + vault).encode("utf-8")).digest()
        if digest.hex() != body.get("sha256") \
                or "def main():" not in code or 'if __name__ == "__main__":' not in code:
            raise ValueError("Обновление пришло повреждённым — попробуйте ещё раз")
        if UPDATE_PUBKEY:   # signature over the digest of exactly these bytes, before anything is written
            try:
                sig_ok = _ed25519_verify(bytes.fromhex(UPDATE_PUBKEY), digest, bytes.fromhex(str(body.get("sig") or "")))
            except ValueError:
                sig_ok = False
            if not sig_ok:
                raise ValueError("Обновление не подписано ключом владельца — не устанавливаю")
        _upapply_set(stage="install", pct=92)
        splice_into(SELF_PATH, code, vault)
        result = {"ok": True, "from": body.get("from"), "created": body.get("created")}
        target = str(request.get("project") or "").strip()
        if target:   # also refresh the project files from the new backup
            result["project"] = vault_extract({"target": target, "force": True})
        try:   # tell the sender it is installed (best effort)
            import urllib.request
            urllib.request.urlopen("%s&id=%s&ok=1" % (_update_url(request, "/mapperx-update/done"), cid), timeout=3).close()
        except Exception:
            pass
        _upapply_set(stage="done", pct=100, done=True, running=False, result=result)
    except ValueError as e:
        _upapply_set(stage="error", error=str(e), done=True, running=False)
    except Exception as e:
        _upapply_set(stage="error", error="Ошибка обновления: %s" % e, done=True, running=False)


def update_apply(request):
    """Starts downloading the update in the background and writes it into this file: the new code
    and project backup, the Pythons / packages blocks of this file stay. Progress: update_progress."""
    url = _update_url(request, "/mapperx-update")
    if not UPDATE_PUBKEY and url.startswith("https://"):
        raise ValueError("В этой копии MapperX нет ключа владельца — обновление через интернет запрещено. "
                         "Обновите её по Wi-Fi (IP Mac) или через USB")
    with UPAPPLY_LOCK:
        if UPAPPLY["running"]:
            raise ValueError("Обновление уже идёт")
        UPAPPLY.update(running=True, stage="connect", pct=0, got=0, total=0, speed=0, eta=None,
                       error=None, done=False, result=None)
    threading.Thread(target=_update_apply_run, args=(request, url), daemon=True).start()
    return {"started": True}


def update_progress(_request):
    with UPAPPLY_LOCK:
        return dict(UPAPPLY)


# ── MapperX Board (Shuffleboard mode): layouts and recordings ──
SB_LAYOUT_DIR = MAPS_DIR / "shuffleboard"
SB_REC_DIR = MAPS_DIR / "recordings"


def _sb_name(name):
    name = safe_name(name)
    if not name:
        raise ValueError("Пустое имя")
    return name


def sb_layout_save(request):
    layout = request.get("layout")
    if not isinstance(layout, dict):
        raise ValueError("Неверная раскладка")
    path = SB_LAYOUT_DIR / (_sb_name(request.get("name")) + ".json")
    write_text(path, json.dumps(layout, ensure_ascii=False, indent=1))
    return {"ok": True, "path": str(path)}


def sb_layout_list(_request):
    files = sorted(SB_LAYOUT_DIR.glob("*.json"), key=lambda p: -p.stat().st_mtime) if SB_LAYOUT_DIR.is_dir() else []
    return {"names": [p.stem for p in files]}


def sb_layout_load(request):
    path = SB_LAYOUT_DIR / (_sb_name(request.get("name")) + ".json")
    if not path.is_file():
        raise ValueError("Нет такой раскладки")
    return {"layout": json.loads(path.read_text(encoding="utf-8"))}


def sb_rec_save(request):
    frames = request.get("frames")
    if not isinstance(frames, list) or not frames:
        raise ValueError("Пустая запись")
    name = time.strftime("rec_%Y%m%d_%H%M%S")
    write_text(SB_REC_DIR / (name + ".json"), json.dumps({"frames": frames}, ensure_ascii=False))
    return {"ok": True, "name": name}


def sb_rec_list(_request):
    files = sorted(SB_REC_DIR.glob("*.json"), key=lambda p: -p.stat().st_mtime) if SB_REC_DIR.is_dir() else []
    return {"names": [p.stem for p in files]}


def sb_rec_load(request):
    path = SB_REC_DIR / (_sb_name(request.get("name")) + ".json")
    if not path.is_file():
        raise ValueError("Нет такой записи")
    return json.loads(path.read_text(encoding="utf-8"))


def splice_into(target, code, vault):
    """Writes new MapperX code + project backup into target (a MapperX file),
    keeping target's own portable Pythons and packages blocks."""
    compile(code, str(target), "exec")   # never write code that would not start
    target = Path(target)
    text = target.read_text(encoding="utf-8")
    v = text.rfind("\n" + VAULT_BEGIN + "\n")
    own = text[:v + 1] if v >= 0 else text
    cuts = [i for i in (own.find("\n" + WHEELS_BEGIN + "\n"), own.find("\n" + PYTHON_MARK)) if i >= 0]
    blocks = own[min(cuts) + 1:] if cuts else ""
    tmp = Path(str(target) + ".update")
    with open(tmp, "w", encoding="utf-8", newline="\n") as out:
        out.write(code.rstrip("\n") + "\n")
        if blocks:
            out.write("\n\n" + blocks.strip("\n") + "\n")
        if vault:
            out.write("\n\n" + vault.lstrip("\n"))
    os.replace(tmp, target)


