def pack_update(dst):
    """MapperX_update/: the code + project backup (no Pythons / packages, a few
    MB) and the scripts that put them into a MapperX_offline.py."""
    code, vault = _split_self()
    dst = Path(dst)
    dst.mkdir(parents=True, exist_ok=True)
    with open(dst / "MapperX_update.py", "w", encoding="utf-8", newline="\n") as out:
        out.write(code.rstrip("\n") + "\n" + ("\n\n" + vault.lstrip("\n") if vault else ""))
    for name, text, nl in (("Обновить MapperX (Windows).cmd", UPDATE_WIN, "\r\n"), ("Обновить MapperX (Mac).command", UPDATE_MAC, "\n")):
        with open(dst / name, "w", encoding="utf-8", newline=nl) as f:
            f.write(text)
    os.chmod(dst / "Обновить MapperX (Mac).command", 0o755)
    return dst, (dst / "MapperX_update.py").stat().st_size


def app_restart(_request):
    """Starts this MapperX again (new code) and ends this process."""
    def later():
        time.sleep(0.5)
        args = [sys.executable, str(SELF_PATH)] + sys.argv[1:]
        if sys.platform == "win32":
            subprocess.Popen(args, creationflags=getattr(subprocess, "CREATE_NEW_CONSOLE", 0))
            os._exit(0)
        os.execv(sys.executable, args)
    threading.Thread(target=later, daemon=True).start()
    return {"ok": True}


def setup_start(request):
    if getattr(sys, "frozen", False):
        raise ValueError("В собранном приложении библиотеки уже внутри")
    wanted = {m["pip"] for m in setup_missing()}
    packages = [p for p in request.get("packages") or sorted(wanted) if p in wanted]
    if not packages:
        raise ValueError("Все библиотеки уже установлены")
    if any(not j.done for j in JOBS.values()):
        raise ValueError("Уже идёт другая задача")
    job_id = secrets.token_hex(4)
    JOBS[job_id] = Job("Установка библиотек", [sys.executable, str(SELF_PATH), "--install", "--yes"] + packages)
    return {"id": job_id, "packages": packages}


