def file_as_data_url(request):
    """An image from disk by path (file pickers may be blocked in VS Code)."""
    path = Path(os.path.expanduser(str(request.get("path") or "").strip().strip('"'))).resolve()
    kinds = {".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".webp": "image/webp", ".bmp": "image/bmp"}
    if path.suffix.lower() not in kinds or not path.is_file():
        raise ValueError("Нужен путь к картинке .png/.jpg/.webp")
    if path.stat().st_size > 15_000_000:
        raise ValueError("Картинка больше 15 МБ")
    return {"data": "data:%s;base64,%s" % (kinds[path.suffix.lower()], base64.b64encode(path.read_bytes()).decode("ascii")),
            "name": path.name}


def vault_save_zip(_request):
    _meta, raw = vault_zip()
    if not raw:
        raise ValueError("Бэкапа ещё нет")
    folder = Path.home() / "Downloads"
    folder = folder if folder.is_dir() else PROJECT_DIR.parent
    out = folder / ("%s_backup_%s.zip" % (PROJECT_DIR.name, time.strftime("%Y%m%d_%H%M%S")))
    out.write_bytes(raw)
    return {"path": str(out)}


