class PadX:
    """Remote pad (PitX «🎮 Пульт»): /pad/send keeps a fresh frame, a thread publishes
    MapperX/pad to the robot at 50 Hz only while the UI keeps sending. The seq number
    changes only while the UI is alive, so the robot watchdog (0.3 s) stops it."""

    FRESH = 0.3
    LIMITS = [(-1, 1)] * 6 + [(-1, 400)] * 3 + [(0, 1)]   # fwd strafe turn lift arm claw | 3 targets | speed
    BINDINGS = MAPS_DIR / "pad_bindings.json"

    def __init__(self):
        self.lock = threading.Lock()
        self.values = None
        self.sent_at = 0.0
        self.seq = 0
        self.thread = None
        self.zero_sent = True

    def start(self):
        if self.thread is None:
            self.thread = threading.Thread(target=self.loop, daemon=True)
            self.thread.start()

    def publish(self, vals):
        inst = BOARDX.inst
        if inst is None or not inst.isConnected():
            return False
        try:
            inst.getEntry("/MapperX/pad").setDoubleArray([float(self.seq)] + [float(v) for v in vals])
        except Exception:  # noqa: BLE001 - NT client being replaced
            return False
        return True

    def loop(self):
        while True:
            time.sleep(0.02)
            with self.lock:
                vals = list(self.values) if self.values else None
                fresh = vals is not None and time.time() - self.sent_at < self.FRESH
                if fresh:
                    self.seq = (self.seq + 1) % 1000000
                    self.zero_sent = False
                elif not self.zero_sent:
                    self.seq = (self.seq + 1) % 1000000   # one last frame: zeros
                    vals = [0.0] * 6 + [-1.0] * 3 + [0.0]
                    self.zero_sent = True
                    fresh = True
            if fresh:
                self.publish(vals)

    def send(self, request):
        v = request.get("v")
        if not isinstance(v, list) or len(v) != 10:
            raise ValueError("Пульт: нужно 10 чисел")
        out = []
        for i, item in enumerate(v):
            if isinstance(item, bool) or not isinstance(item, (int, float)) or not math.isfinite(item):
                raise ValueError("Пульт: неверное число №%d" % i)
            lo, hi = self.LIMITS[i]
            x = min(hi, max(lo, float(item)))
            if 6 <= i <= 8 and x < 0:
                x = -1.0
            out.append(x)
        inst = BOARDX.inst
        if inst is None or not inst.isConnected():
            raise ValueError("Нет связи с роботом")
        with self.lock:
            self.values = out
            self.sent_at = time.time()
        self.start()
        return {"ok": True}

    def stop(self, _request):
        with self.lock:
            self.values = None
            self.zero_sent = True
            self.seq = (self.seq + 1) % 1000000
        self.publish([0.0] * 6 + [-1.0] * 3 + [0.0])
        return {"ok": True}

    def status(self, _request):
        inst = BOARDX.inst
        connected = bool(inst is not None and inst.isConnected())
        state = ""
        if connected:
            try:
                state = str(inst.getEntry("/MapperX/padState").value or "")
            except Exception:  # noqa: BLE001
                state = ""
        age = time.time() - self.sent_at if self.sent_at else None
        return {"connected": connected, "padState": state,
                "lastSendAge": None if age is None else round(age, 2)}

    def bindings(self, request):
        save = request.get("save")
        if save is not None:
            if not isinstance(save, dict):
                raise ValueError("Назначения: нужен объект")
            raw = json.dumps(save, ensure_ascii=False)
            if len(raw.encode("utf-8")) > 200 * 1024:
                raise ValueError("Назначения слишком большие")
            MAPS_DIR.mkdir(exist_ok=True)
            tmp = Path(str(self.BINDINGS) + ".tmp")
            tmp.write_text(raw, encoding="utf-8")
            os.replace(tmp, self.BINDINGS)
            return {"ok": True, "data": save}
        try:
            return {"ok": True, "data": json.loads(self.BINDINGS.read_text(encoding="utf-8"))}
        except (OSError, ValueError):
            return {"ok": True, "data": {}}


PADX = PadX()
