def _console_utf8():
    # Windows consoles (cp866 / cp1251) cannot print «—» and Russian everywhere
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(encoding="utf-8", errors="replace")
        except (AttributeError, ValueError):
            pass


def cli_install(args):
    """python field_planner.py --install [--yes] [packages…]"""
    missing = setup_missing()
    asked = [a for a in args if not a.startswith("--")]
    packages = [m["pip"] for m in missing if not asked or m["pip"] in asked]
    print("MapperX: %s, Python %s (%s)" % (setup_os(), sys.version.split()[0], sys.executable))
    if not packages:
        print("Все нужные библиотеки уже установлены.")
        return 0
    print("Не хватает:")
    for m in missing:
        if m["pip"] in packages:
            print("  %-24s %s" % (m["pip"], m["why"]))
    if "--yes" not in args:
        try:
            if input("Установить? [Y/n] ").strip().lower() not in ("", "y", "yes", "д", "да"):
                return 1
        except EOFError:
            return 1
    return 0 if setup_install(packages) else 1


def run_app(server, url):
    """MapperX in its own window (pywebview: WebKit on macOS, Edge WebView2 on
    Windows), opening on the Shuffleboard-style dashboard."""
    import webview
    from webview.menu import Menu, MenuAction, MenuSeparator
    studios = [("map", "MapperX — карта, маршрут"), ("detect", "DetectX — камера, HSV"), ("tune", "TuneX — параметры"),
               ("construct", "ConstructX — конструктор кода"), ("board", "BoardX — NetworkTables"),
               ("pin", "PinX — распиновка"), ("pit", "PitX — перед заездом"), ("vault", "VaultX — бэкап, сборка, деплой")]
    window = webview.create_window("MapperX Board", url + "?sb=1", width=1400, height=900, min_size=(900, 600),
                                   background_color="#F5F5F5", text_select=True)

    def panel():
        window.evaluate_js("if (typeof sbEnabled === 'function' && sbEnabled()) sbShow(true); else location.search = '?sb=1';")

    def studio(key):
        def go():
            window.evaluate_js("if (typeof sbEnabled === 'function' && sbEnabled()) sbOpenStudio('%s'); else setStudio('%s');" % (key, key))
        go.__name__ = "studio_" + key
        return go

    def full():
        window.evaluate_js("location.search = '';")

    items = [MenuAction("Панель Shuffleboard", panel), MenuSeparator()]
    items += [MenuAction(title, studio(key)) for key, title in studios]
    items += [MenuSeparator(), MenuAction("Полный интерфейс MapperX", full)]

    def shortcuts():
        # menu items get Cmd+Shift+0…8 on macOS (the page alone does not see them in WebKit)
        if sys.platform != "darwin":
            return
        import AppKit

        def apply():
            keys = {"Панель Shuffleboard": "0"}
            keys.update({title: str(n + 1) for n, (_k, title) in enumerate(studios)})
            main_menu = AppKit.NSApp.mainMenu()
            for i in range(main_menu.numberOfItems()):
                sub = main_menu.itemAtIndex_(i).submenu()
                if sub is None or sub.title() != "Вид":
                    continue
                for j in range(sub.numberOfItems()):
                    item = sub.itemAtIndex_(j)
                    if item.title() in keys:
                        item.setKeyEquivalent_(keys[item.title()])
                        item.setKeyEquivalentModifierMask_(AppKit.NSEventModifierFlagCommand | AppKit.NSEventModifierFlagShift)
        AppKit.NSOperationQueue.mainQueue().addOperationWithBlock_(apply)

    threading.Thread(target=server.serve_forever, daemon=True).start()
    webview.start(shortcuts, private_mode=False, menu=[Menu("Вид", items)])
    server.shutdown()


def main():
    _console_utf8()
    args = sys.argv[1:]
    if "--install" in args:
        sys.exit(cli_install(args))
    if "--apply-to" in args:
        target = Path(args[args.index("--apply-to") + 1]).resolve()
        code, vault = _split_self()
        print("Обновляю %s новым кодом MapperX и бэкапом проекта (Python и библиотеки в нём остаются)…" % target, flush=True)
        splice_into(target, code, vault)
        print("Готово: %s обновлён. Запускайте MapperX как обычно." % target.name, flush=True)
        return
    if "--pack-update" in args:
        dst, size = pack_update(SELF_PATH.parent / "MapperX_update")
        print("Готово: %s (%.1f МБ). Скопируйте MapperX_update.py и «Обновить MapperX (Windows).cmd» в папку "
              "MapperX_offline на другом ноутбуке и запустите .cmd." % (dst, size / 1e6), flush=True)
        return
    if "--pack-offline" in args or "--embed-light" in args:
        light = "--embed-light" in args
        dst = SELF_PATH if light else SELF_PATH.parent / "MapperX_offline"
        print("Упаковываю офлайн-пакеты в %s…" % dst.name, flush=True)
        n, npy, path, size = pack_offline(dst, light=light)
        print("Готово: %s — %d пакетов, %d Python, %.0f МБ. %s" % (path, n, npy, size / 1e6,
              "Внутри: связь с роботом и окно-приложение." if light else
              "Перенесите всю папку %s на другой ноутбук и запустите «Запустить MapperX (Windows).cmd» "
              "или «Запустить MapperX (Mac).command»: Python и библиотеки ставятся без интернета." % dst.name), flush=True)
        return
    app = "--app" in args
    auto = not getattr(sys, "frozen", False) and "--no-install" not in args and not os.environ.get("MAPPERX_NO_INSTALL")
    missing = [m["pip"] for m in setup_missing()] if auto else []
    # robot link (and the window for --app) right now, the rest (numpy, opencv…) in the background
    now = [p for p in missing if p == "pynetworktables" or (app and p == "pywebview")]
    setup_auto(now, background=False)
    setup_auto([p for p in missing if p not in now], background=True)
    if app and any(m["module"] == "webview" for m in setup_missing()):
        print("Для --app нужна библиотека pywebview, а поставить её не удалось — см. сообщения выше.")
        sys.exit(1)
    if app:
        os.environ["MAPPERX_PORT"] = os.environ.get("MAPPERX_PORT", "0")
    if "--port" in args:
        os.environ["MAPPERX_PORT"] = args[args.index("--port") + 1]
    in_vscode = os.environ.get("TERM_PROGRAM") == "vscode"
    no_browser = "--no-browser" in args or os.environ.get("MAPPERX_NO_BROWSER") or in_vscode
    server = PlannerServer()
    url = "http://127.0.0.1:%d/" % server.server_port
    print("MapperX: %s  (Ctrl+C — стоп)" % url, flush=True)
    if in_vscode:
        print("VS Code: Cmd/Ctrl+Shift+P → «Simple Browser: Show» → вставьте %s" % url, flush=True)
        print("  (или Cmd/Ctrl+клик по ссылке — откроется в обычном браузере)", flush=True)
    LIVEX.start()
    if app:
        run_app(server, url)
        return
    if not no_browser:
        # --shuffleboard: the MapperX Board dashboard (Shuffleboard look) first
        webbrowser.open(url + ("?sb=1" if "--shuffleboard" in args else ""))
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()


if __name__ == "__main__":
    main()


